def runtime_install(a,root):
 confirm(a)
 if os.geteuid()!=0:raise ValueError('runtime-install requires root')
 platform_check(dict(architectures=['any'],min_panel_version=PANEL),root)
 destination=no_symlinks(runtime_path());destination.mkdir(parents=True,exist_ok=True,mode=0o755)
 with lock(root):
  for p in [HERE/'ozsdk.py',*(HERE/'lib').glob('*.py'),*(HERE/'lib').glob('*.sh')]:
   rel=p.relative_to(HERE);target=destination/rel
   if target.exists() and target.read_bytes()!=p.read_bytes():write(str(target)+'.before-sdk-update',target.read_bytes(),0o600)
   write(target,p.read_bytes(),0o755 if p.name=='ozsdk.py' else 0o644)
