def core_trust_cmd(a):
 i=addon_id(a.id)
 if not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9_.-]{0,127}',a.product):raise ValueError('Invalid product')
 pub=Path(a.public).resolve()
 if not pub.is_file():raise ValueError('Public key file not found')
 detail=openssl(['pkey','-pubin','-in',str(pub),'-text','-noout'])
 if b'ED25519' not in detail:raise ValueError('Ed25519 publisher key required')
 out={
  'addon_id':int(i),
  'product':a.product,
  'public_key_sha256':hashlib.sha256(pub.read_bytes()).hexdigest(),
  'commands':{
   'core_trust':f'sudo /usr/bin/oz --addon-license-trust {i} {shlex.quote(str(pub))} {shlex.quote(a.product)} --confirm',
   'core_import':f'sudo /usr/bin/oz --addon-license-import {i} /path/to/license.json /path/to/license.json.sig',
   'core_check':f'sudo /usr/bin/oz --addon-entitlement {i}'
  }
 }
 print(json.dumps(out,indent=2,ensure_ascii=False))

def inspect_lease_status(root,now=None):
 native_dir=Path(root)/'native'
 lease_path=native_dir/'runtime.lease'
 boot_id=None
 try:boot_id=Path('/proc/sys/kernel/random/boot_id').read_text().strip()
 except OSError:pass
 now_ts=int(time.time() if now is None else now)
 if not lease_path.is_file():
  return {
   'present':False,
   'valid_size':False,
   'sealed':False,
   'protocol':'ozv8-fortress/1',
   'expected_bytes':LEASE_BYTES,
   'actual_bytes':0,
   'expires_at':None,
   'ttl_remaining':0,
   'expired':True,
   'boot_id':boot_id,
   'wrap_binding':'OZV7-HW-WRAP/1:<device_id>:<machine-id>:<boot_id>',
   'mac_binding':'OZV7-LEASE-MAC/1'
  }
 raw=lease_path.read_bytes()
 valid_size=(len(raw)==LEASE_BYTES)
 expires_at=None;ttl=0;expired=True
 if valid_size:
  expires_at=struct.unpack('>Q',raw[32:40])[0]
  ttl=max(0,int(expires_at-now_ts))
  expired=(now_ts>expires_at)
 return {
  'present':True,
  'valid_size':valid_size,
  'sealed':bool(valid_size and not expired),
  'protocol':'ozv7-fortress/1',
  'expected_bytes':LEASE_BYTES,
  'actual_bytes':len(raw),
  'expires_at':expires_at,
  'ttl_remaining':ttl,
  'lease_ttl_policy_seconds':LEASE_TTL_SECONDS,
  'expired':expired,
  'boot_id':boot_id,
  'wrap_binding':'OZV7-HW-WRAP/1:<device_id>:<machine-id>:<boot_id>',
  'mac_binding':'OZV7-LEASE-MAC/1'
 }

